namespace L0 {
  static float s_timeAcc = 0.0f;

  void setup() {
    PFMath::buildSinLUT();
    s_timeAcc = 0.0f;
  }

  void update(float dt, const InputFrame& input) {
    (void)input;
    float speed = knobVal[1];
    s_timeAcc += dt * speed;
    if (s_timeAcc >= TWO_PI * 100.0f) {
      s_timeAcc -= TWO_PI * 100.0f;
    }
  }

  void draw() {
    const float cx = FRAME_W * 0.5f;
    const float cy = FRAME_H * 0.5f;
    const int tileSize = 8;

    float quantize = knobVal[0];
    float phaseShift = knobVal[2];
    float sharpness = knobVal[3];

    bool useQuantize = (quantize > 1.0f);
    float qStep = useQuantize ? (1.0f / quantize) : 1.0f;

    for (int y = 0; y < FRAME_H; ++y) {
      bool isRowBorder = ((y % tileSize) == 0);
      int gridY = y / tileSize;
      float ty = gridY * tileSize + tileSize * 0.5f;
      float dy = ty - cy;

      for (int x = 0; x < FRAME_W; ++x) {
        if (isRowBorder || (x % tileSize) == 0) {
          L0_setValue(x, y, 0.0f);
          continue;
        }

        int gridX = x / tileSize;
        float tx = gridX * tileSize + tileSize * 0.5f;
        float dx = tx - cx;

        float dist = sqrtf(dx * dx + dy * dy);

        float localTime = s_timeAcc - dist * phaseShift * 0.08f;
        if (useQuantize) {
          localTime = floorf(localTime / qStep) * qStep;
        }

        float wave = PFMath::fastSin(dist * 0.25f - localTime * 3.0f);
        float val = (wave + 1.0f) * 0.5f;

        if (val <= 0.0f) {
          val = 0.0f;
        } else if (val >= 1.0f) {
          val = 1.0f;
        } else {
          val = PFMath::fastPow(val, sharpness);
        }

        if (val < 0.0f) val = 0.0f;
        if (val > 1.0f) val = 1.0f;

        L0_setValue(x, y, val);
      }
    }
  }
}
