namespace L2 {
  static float s_t = 0.0f;

  void setup() {
    PFMath::buildSinLUT();
    s_t = 0.0f;
  }

  void update(float dt, const InputFrame& input) {
    (void)input;
    float speed = knobVal[1];
    s_t += dt * speed;
    if (s_t >= TWO_PI * 100.0f) {
      s_t -= TWO_PI * 100.0f;
    }
  }

  void draw() {
    const int W = FRAME_W;
    const int H = FRAME_H;
    const bool portrait = (W < H);
    const float vw = portrait ? (float)W : (float)H;
    const float vh = portrait ? (float)H : (float)W;

    const float amp = knobVal[0];
    const float sun = knobVal[2];
    const float glit = knobVal[3];

    const float horizon = floorf(vh * 0.34f);
    const float beachTop = vh - floorf(vh * 0.14f);
    const float sunU = vw * 0.5f;
    const float sunV = horizon - 3.0f - sun * (horizon - 8.0f);

    const int stepT = (int)(s_t * 7.0f);

    for (int y = 0; y < H; ++y) {
      for (int x = 0; x < W; ++x) {
        float u, v;
        if (portrait) {
          u = (float)x;
          v = (float)y;
        } else {
          u = (float)y;
          v = (float)(W - 1 - x);
        }

        float val = 0.0f;

        if (v < horizon) {
          float g = v / horizon;
          val = 0.12f + 0.38f * g;

          float du = u - sunU;
          float dv = (v - sunV) * 1.2f;
          float d = sqrtf(du * du + dv * dv);
          if (d < 4.5f) {
            val = 1.0f;
          } else {
            val += 0.7f * expf(-d * 0.18f);
          }

          float cl = PFMath::fastSin(u * 0.11f + v * 0.9f + s_t * 0.25f)
                   + PFMath::fastSin(u * 0.05f - v * 0.5f + 2.0f);
          if (cl > 1.2f && v < horizon * 0.8f) {
            val += 0.12f;
          }
        } else if (v < beachTop) {
          float depth = (v - horizon) / (beachTop - horizon);
          float persp = 1.0f / (depth + 0.09f);
          float wob = PFMath::fastSin(u * 0.25f + s_t * 1.3f) * 0.5f * amp;
          float band = PFMath::fastSin(persp * 2.6f + wob + s_t * (1.5f + depth * 2.0f));
          val = 0.42f - 0.22f * depth
              + band * (0.06f + 0.14f * amp) * (0.4f + depth);

          float pathW = 2.5f + depth * 9.0f;
          float sway = PFMath::fastSin(v * 0.5f + s_t) * amp * 2.0f;
          bool inPath = (fabsf(u - sunU + sway) < pathW);
          if (inPath) {
            val += 0.12f + 0.10f * (1.0f - depth);
          }

          float sp = PFNoise::cellHash((int)u, (int)v, stepT);
          float thr = 1.0f - glit * (inPath ? 0.10f : 0.03f);
          if (sp > thr && band > 0.2f) {
            val = 1.0f;
          }
        } else {
          float s = (v - beachTop) / (vh - beachTop);
          val = 0.5f + 0.15f * s + 0.06f * PFNoise::cellHash((int)u, (int)v);

          float surge = PFMath::fastSin(s_t * 1.8f) * 0.5f + 0.5f;
          float edge = beachTop
                     + 2.0f + surge * (vh - beachTop) * 0.55f * (0.4f + amp)
                     + PFMath::fastSin(u * 0.35f + s_t * 2.2f) * 2.5f * amp;

          if (v < edge) {
            val = 0.34f - 0.10f * (edge - v) / (vh - beachTop);
            if (edge - v < 1.5f) {
              val = 0.95f;
            }
          }
        }

        if (val < 0.0f) val = 0.0f;
        if (val > 1.0f) val = 1.0f;

        L2_setValue(x, y, val);
      }
    }
  }
}
